H.background();
const g = 9.8;
const speed = P.speed;
const angDeg = P.angle;
const ang = angDeg * Math.PI / 180;
const vx = speed * Math.cos(ang);
const vy = speed * Math.sin(ang);
const tFlight = Math.max(0.001, 2 * vy / g);
const range = vx * tFlight;
const maxH = (vy * vy) / (2 * g);
const xMax = Math.max(range * 1.1, 1);
const yMax = Math.max(maxH * 1.3, 1);
const view = H.plot2d({ xMin: 0, xMax: xMax, yMin: 0, yMax: yMax });
view.grid(); view.axes();
const pts = [];
for (let i = 0; i <= 50; i++) {
  const tt = tFlight * i / 50;
  pts.push([vx * tt, vy * tt - 0.5 * g * tt * tt]);
}
view.path(pts, { color: H.colors.accent, width: 3 });
const tc = (t % (tFlight + 0.6));
const tp = Math.min(tc, tFlight);
const xp = vx * tp;
const yp = Math.max(0, vy * tp - 0.5 * g * tp * tp);
view.dot(xp, yp, { r: 7, fill: H.colors.warn });
view.dot(range / 2, maxH, { r: 5, fill: H.colors.good });
